import React, { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';

function ToyDetails() {
    const { id } = useParams();
    const [toy, setToy] = useState(null);

    useEffect(() => {
        async function fetchToyDetails() {
            try {
                const response = await fetch(`${process.env.REACT_APP_TOY_SERVICE_URL}/toys/${id}`, {
                    method: 'GET',
                    headers: {
                        'Authorization': 'Bearer ' + localStorage.token
                    },
                });
                const data = await response.json();
                setToy(data);
            } catch (error) {
                console.error('Error fetching toy details:', error);
            }
        }

        fetchToyDetails();
    }, [id]);

    if (!toy) {
        return <div>Loading...</div>;
    }

    return (
        <div>
            <div>
                <img src={`${process.env.REACT_APP_TOY_SERVICE_URL}/Images/${toy.imageUrl}`} alt={toy.name} />
            </div>
            <div>
                <h1>{toy.name}</h1>
                <p>{toy.description}</p>
                <p>Age Range: {toy.ageRange}</p>
                <p>Category: {toy.categoryId}</p>
                <p>Price: ${toy.price}</p>
            </div>

            <div>
                <Link to={`/toys/${toy.id}`} className="buybutton" id="button">добавить</Link>
            </div>

        </div>
    );
}

export default ToyDetails;
